import sys
import os
import html
import re

def escape_html(text):
    return html.escape(text)

def apply_inline_formatting(text):
    # Bold: **text** or __text__
    text = re.sub(r'\*\*(.*?)\*\*', r'<strong>\1</strong>', text)
    text = re.sub(r'__(.*?)__', r'<strong>\1</strong>', text)
    # Italic: *text* or _text_
    text = re.sub(r'\*(.*?)\*', r'<em>\1</em>', text)
    text = re.sub(r'_(.*?)_', r'<em>\1</em>', text)
    # Inline code: `code`
    text = re.sub(r'`(.*?)`', r'<code>\1</code>', text)
    return text

def convert(markdown: str) -> str:
    lines = markdown.split("\n")
    blocks = []
    current_block_type = None
    current_block_content = []

    def add_block():
        if current_block_content:
            blocks.append((current_block_type, "\n".join(current_block_content)))
        current_block_content.clear()

    for line in lines:
        stripped_line = line.strip()

        if stripped_line == "```":
            if current_block_type == "code_fence":
                add_block()
                current_block_type = None
            else:
                add_block()
                current_block_type = "code_fence"
        elif stripped_line.startswith("#") and current_block_type != "code_fence":
            add_block()
            current_block_type = "heading"
            current_block_content.append(line)
        elif stripped_line.startswith("- ") and current_block_type != "code_fence":
            add_block()
            current_block_type = "list"
            current_block_content.append(line)
        elif not stripped_line and current_block_type != "code_fence":
            add_block()
            current_block_type = None
        else:
            if current_block_type != "code_fence":
                if current_block_type == "paragraph":
                    current_block_content.append(line)
                else:
                    add_block()
                    current_block_type = "paragraph"
                    current_block_content.append(line)
            else:
                current_block_content.append(line)

    add_block() # Add the last block

    html_output = []
    for block_type, content in blocks:
        if block_type == "code_fence":
            escaped_content = escape_html(content)
            html_output.append(f"<pre><code>{escaped_content}</code></pre>")
        elif block_type == "heading":
            level = 0
            heading_text = content.strip()
            while heading_text.startswith("#"):
                level += 1
                heading_text = heading_text[1:]
            text = heading_text.strip()[1:].strip() # Remove '#' and leading space
            formatted_text = apply_inline_formatting(text)
            html_output.append(f"<h{level}>{formatted_text}</h{level}>")
        elif block_type == "list":
            html_output.append("<ul>")
            for item in content.split("\n"):
                if item.strip().startswith("- "):
                    list_item_text = item.strip()[2:].strip()
                    formatted_item = apply_inline_formatting(list_item_text)
                    html_output.append(f"<li>{formatted_item}</li>")
            html_output.append("</ul>")
        elif block_type == "paragraph":
            processed_content = content.strip()
            formatted_paragraph = apply_inline_formatting(processed_content)
            html_output.append(f"<p>{formatted_paragraph}</p>")

    final_output = "\n".join(html_output)
    if final_output:
        return final_output + "\n"
    else:
        return ""

